struct Draft { std::string sku; std::optional<int> qty; };

// nullopt == no error; C++23: std::expected<void, ValidationError>
std::optional<std::string> validate_for_publish(const Draft& d);

void publish(Draft& d) {
    if (auto err = validate_for_publish(d)) { report(*err); return; }  // gate first
    bus.publish(encode(d));                                            // irreversible step
}
